import { cacheTag } from 'next/cache'

export interface Product {
  id: string
  name: string
  sku: string
  price: number
  inventory: number
  available: boolean
  updatedAt: string
}

export async function getProducts(): Promise<Product[]> {
  'use cache'
  cacheTag('products')

  // In production, this would query your ERP/PIM or database.
  // The result is cached and reused across requests until revalidated.
  const res = await fetch('https://dummyjson.com/products?limit=20', {
    next: { tags: ['products'] },
  })

  if (!res.ok) {
    throw new Error('Failed to fetch products')
  }

  const json = await res.json()

  return json.products.map((p: any) => ({
    id: String(p.id),
    name: p.title,
    sku: `SKU-${p.id}`,
    price: p.price,
    inventory: p.stock,
    available: p.stock > 0,
    updatedAt: new Date().toISOString(),
  }))
}

